        let c = self.codes[j];
        matches!(c & 0xff, 9) && !matches!(c >> 8 & 0xff, 10 | 62 | 13 | 61 | 45 | 54 | 117 | 42 | 14 | 53 | 43 | 15 | 75 | 118 | 31 | 60 | 38 | 37 | 59 | 116 | 56 | 11 | 22 | 23 | 55 | 44 | 103 | 104 | 105)
